// Extrai número do cliente e texto da mensagem recebida.
// Ignora eventos de status (sem value.messages).
const entry = ((($json.body && $json.body.entry) || $json.entry || [])[0]) || {};
const change = ((entry.changes || [])[0]) || {};
const value = change.value || {};
if (!value.messages || !value.messages.length) return [];
const msg = value.messages[0];
const from = msg.from || '';
const texto = (msg.type === 'text' && msg.text) ? msg.text.body : '';
if (!from || !texto) return [];
return [{ from, texto }];

// Combina a config (do admin) com a mensagem e monta os payloads.
const cfg = $json;
const msg = $('Extrair Mensagem').item.json;
const r = (s) => (s || '')
  .replaceAll('{{agente_nome}}', cfg.agente_nome || '')
  .replaceAll('{{empresa_nome}}', cfg.empresa_nome || '')
  .replaceAll('{{servico_principal}}', cfg.servico_principal || '')
  .replaceAll('{{criterio_alto_valor}}', cfg.criterio_alto_valor || '')
  .replaceAll('{{link_app}}', cfg.link_app || '')
  .replaceAll('{{base_conhecimento}}', cfg.base_conhecimento || '');
const system = r(cfg.system_message).replaceAll('{{modelos}}', JSON.stringify(cfg.modelos || []));
const base = (cfg.llm && cfg.llm.base_url) || 'http://127.0.0.1:8888/v1';
const model = (cfg.llm && cfg.llm.model) || 'unsloth/gemma-4-12B-it-qat-GGUF';
const phone = (cfg.meta && cfg.meta.phone_number_id) || '';
const version = (cfg.meta && cfg.meta.version) || 'v25.0';
return [{
  from: msg.from,
  llm_url: base + '/chat/completions',
  llm_body: JSON.stringify({ model, messages: [{ role: 'system', content: system }, { role: 'user', content: msg.texto }], max_tokens: 400 }),
  llm_key: (cfg.llm && cfg.llm.api_key) || '',
  wa_url: 'https://graph.facebook.com/' + version + '/' + phone + '/messages',
  wa_token: (cfg.meta && cfg.meta.access_token) || ''
}];

// Extrai a resposta do LLM e monta o payload do WhatsApp.
const content = (((($json.choices || [])[0] || {}).message || {}).content || '').trim();
if (!content) return [];
const p = $('Montar Prompt').item.json;
return [{
  resposta: content,
  wa_url: p.wa_url,
  wa_token: p.wa_token,
  wa_body: JSON.stringify({ messaging_product: 'whatsapp', to: p.from, type: 'text', text: { body: content } })
}];
